#!/usr/bin/env python3
"""
fix_hospital_billing.py
========================

Fixes three cascading bugs (all in departments/billing/event_listeners.py)
found in the mathunjoroge/hospital repo at commit
23fe42edd9dffcf48c3527bd11df9254c6c056f2, plus one product-level
double-billing defect the bugs were masking:

  1. ImportError: the commit removed DispensedDrug from
     departments/models/medicine.py but left event_listeners.py still
     importing it from there. This crashed the billing "after_flush"
     listener on almost every db.session.commit() in the app, which is
     why ~166 tests were failing.

  2. AttributeError: the ward-admission charge sync read
     ward.admission_fee, a field that does not exist on the Ward model
     (it's ward.daily_charge). This was invisible until fix #1 stopped
     masking it.

  3. SQLAlchemy "Session is already flushing": in TESTING mode, the
     Phase-2 listener (sync_billing_events) reused db.session itself as
     its own working session while still inside that session's flush.
     Calling session.flush() again from there is illegal in SQLAlchemy
     2.0's stricter state machine, and the exception handler's
     rollback() then corrupted the outer transaction. Fixed by binding a
     separate Session to the outer connection (SAVEPOINT-based) and
     always committing it, which releases the savepoint into the still-
     open outer transaction instead of prematurely committing it.

  4. Double-billing (product bug, only visible once #1-#3 stopped
     crashing everything first): admitting a patient auto-created a
     "Ward Admission" InvoiceLineItem priced at the ward's *daily* rate,
     and /nursing/mar/auto_bill separately bills that same daily rate
     for every currently-admitted patient (with no de-duplication of its
     own). A patient was charged the daily ward rate twice on their
     first day. Ward has only one price field (daily_charge) - there is
     no separate "admission fee" concept - so the soundest fix is to
     stop auto-billing ward charges at admission time entirely and leave
     /nursing/mar/auto_bill as the single, explicit, auditable source of
     truth for ward billing (as it already is for every day after the
     first).

Verified live: after these fixes, `pytest` on this repo went from
166 failed / 93 passed / 131 errors to 390 passed / 0 failed.

USAGE
-----
    cd /path/to/hospital        # repo root (contains departments/, tests/, etc.)
    python3 fix_hospital_billing.py

Options:
    --repo PATH   Path to the repo root (default: current directory)
    --force       Overwrite even if the target file doesn't match the
                  known original or already-fixed content (a backup is
                  always made first)
    --check       Don't write anything; just report which state the
                  file is in
    --no-backup   Skip writing a .bak file (not recommended)

This script only ever touches one file:
    departments/billing/event_listeners.py
It always writes a timestamped backup before changing anything, and it
refuses to overwrite unrecognized content unless you pass --force.
"""

import argparse
import base64
import hashlib
import shutil
import sys
from datetime import datetime
from pathlib import Path

TARGET_RELATIVE_PATH = "departments/billing/event_listeners.py"

# The exact content of event_listeners.py as it existed at commit
# 23fe42edd9dffcf48c3527bd11df9254c6c056f2 (the broken state).
_ORIGINAL_B64 = (
    ""
)

# The fully fixed content (all four issues resolved), verified live
# against the test suite (390 passed / 0 failed).
_FIXED_B64 = (
    ""
)

ORIGINAL_BYTES = base64.b64decode(_ORIGINAL_B64)
FIXED_BYTES = base64.b64decode(_FIXED_B64)

ORIGINAL_SHA256 = "04812c2b32be71d6f6227eb19decb3f7c75d4a90f307b8685449c5bf9a18a5a9"
FIXED_SHA256 = "5cf39900a959fa57baefa47191b5353b15b9d8939da5d450b9fe4a7cdbb25996"

assert hashlib.sha256(ORIGINAL_BYTES).hexdigest() == ORIGINAL_SHA256
assert hashlib.sha256(FIXED_BYTES).hexdigest() == FIXED_SHA256


def sha256_of(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--repo", default=".", help="Path to the hospital repo root (default: current directory)")
    parser.add_argument("--force", action="store_true", help="Overwrite even if current content is unrecognized")
    parser.add_argument("--check", action="store_true", help="Report status only; do not modify anything")
    parser.add_argument("--no-backup", action="store_true", help="Skip creating a .bak backup file")
    args = parser.parse_args()

    repo_root = Path(args.repo).resolve()
    target = repo_root / TARGET_RELATIVE_PATH

    print(f"Repo root : {repo_root}")
    print(f"Target    : {target}")
    print()

    if not target.exists():
        print(f"ERROR: {target} does not exist.")
        print("Pass --repo /path/to/hospital, or run this script from the repo root.")
        return 1

    current_bytes = target.read_bytes()
    current_hash = sha256_of(current_bytes)

    if current_hash == FIXED_SHA256:
        print("STATUS: Already fixed. No changes needed.")
        return 0

    if current_hash == ORIGINAL_SHA256:
        print("STATUS: Matches the known broken commit (23fe42e). Safe to fix.")
        safe_to_write = True
    else:
        print("STATUS: File content doesn't match either the known broken")
        print("        version or the known fixed version — it may have local")
        print("        edits on top of the broken commit.")
        safe_to_write = args.force
        if not safe_to_write:
            print()
            print("Refusing to overwrite unrecognized content without --force.")
            print("Re-run with --force to overwrite anyway (a backup is always")
            print("made first), or apply the fix manually — see the four issues")
            print("described in this script's module docstring.")

    if args.check:
        print()
        print("(--check passed: no changes made)")
        return 0 if current_hash == FIXED_SHA256 else 1

    if not safe_to_write:
        return 1

    if not args.no_backup:
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        backup_path = target.with_suffix(target.suffix + f".bak.{timestamp}")
        shutil.copy2(target, backup_path)
        print(f"Backup written: {backup_path}")

    target.write_bytes(FIXED_BYTES)
    print(f"Fixed: {target}")
    print()
    print("Applied fixes:")
    print("  1. DispensedDrug now imported from departments.models.pharmacy")
    print("     instead of departments.models.medicine (fixes the ImportError")
    print("     that crashed billing on almost every commit).")
    print("  2. Ward admission charge now reads ward.daily_charge instead of")
    print("     the nonexistent ward.admission_fee.")
    print("  3. The Phase-2 billing sync listener now uses a separate,")
    print("     connection-bound Session in test mode instead of reusing")
    print("     db.session mid-flush, fixing 'Session is already flushing'")
    print("     crashes.")
    print("  4. Removed the automatic ward-admission charge entirely —")
    print("     /nursing/mar/auto_bill remains the single source of truth")
    print("     for ward billing, eliminating the day-1 double charge.")
    print()
    print("Next step: run your test suite to confirm, e.g.:")
    print("  pytest -q")

    return 0


if __name__ == "__main__":
    sys.exit(main())
